<script setup lang="ts">
import { VideoPlay, Check, Trophy } from '@element-plus/icons-vue'
import type { LearningPath, PathStepStatus } from '../../types/path'
defineProps<{ path: LearningPath; updatingStep: number | null }>()
const emit = defineEmits<{ update: [step: number, status: PathStepStatus] }>()
const labels: Record<string,string>={document:'讲义',quiz:'测验',mindmap:'思维导图',video_script:'视频脚本',code_case:'代码实例'}
</script>
<template><section class="timeline" aria-label="学习路径步骤"><article v-for="item in path.path_data" :key="item.step" :class="['step',item.status]"><div class="node"><Check v-if="item.status==='completed'"/><span v-else>{{ item.step }}</span></div><div class="content"><div class="meta"><span>第 {{ item.step }} 站</span><span>{{ item.estimated_minutes }} 分钟</span></div><h2>{{ item.topic }}</h2><p>{{ item.description }}</p><div class="tags"><span v-for="type in item.resource_types_needed" :key="type">{{ labels[type] || type }}</span></div><div class="actions"><template v-if="item.status==='pending'"><button class="start" :disabled="updatingStep!==null" @click="emit('update',item.step,'in_progress')"><VideoPlay/>开始这一站</button></template><template v-else-if="item.status==='in_progress'"><button class="complete" :disabled="updatingStep!==null" @click="emit('update',item.step,'completed')"><Check/>标记完成</button></template><span v-else class="done"><Trophy/>已点亮</span></div></div></article></section></template>
